/* Reseñas reales de clientes. Formato: { texto: "...", nombre: "Nombre", detalle: "Producto o comuna" } */
const RESENAS = [];

function Opiniones() {
  return (
    <section className="ee-sec ee-sec--soft ee-band--crema ee-opiniones" aria-label="Opiniones de clientes">
      <SectionHeading overline="Opiniones" title="Lo que dicen" script="nuestras clientas" />
      <div className="ee-opiniones__grid">
        {RESENAS.map(r => <Testimonial key={r.nombre + r.texto.slice(0, 12)} quote={r.texto} author={r.nombre} meta={r.detalle} />)}
      </div>
    </section>
  );
}

/* Reseñas: las clientas califican y comentan; cada reseña se publica cuando se aprueba en /resenas-admin. */
function Estrellas({ valor, onElegir }) {
  const [sobre, setSobre] = React.useState(0);
  const v = sobre || valor;
  return (
    <span className="ee-rs__stars" role="radiogroup" aria-label="Calificación" onMouseLeave={() => setSobre(0)}>
      {[1, 2, 3, 4, 5].map(n => (
        <button key={n} type="button" role="radio" aria-checked={valor === n} aria-label={n + (n === 1 ? " estrella" : " estrellas")}
          className={"ee-rs__star" + (n <= v ? " is-on" : "")} onMouseEnter={() => setSobre(n)} onClick={() => onElegir(n)}>★</button>
      ))}
    </span>
  );
}

function Resenas() {
  const [datos, setDatos] = React.useState(null);
  const [abierto, setAbierto] = React.useState(false);
  const [f, setF] = React.useState({ nombre: "", producto: "", texto: "", estrellas: 0, sitio: "" });
  const [estado, setEstado] = React.useState({ enviando: false, error: "", listo: false });
  React.useEffect(() => {
    fetch("/api/resenas", { cache: "no-store" }).then(r => r.json()).then(j => setDatos(j.ok ? j : { resenas: [] })).catch(() => setDatos({ resenas: [] }));
  }, []);
  const campo = (k) => (e) => setF({ ...f, [k]: e.target.value });
  const enviar = (e) => {
    e.preventDefault();
    if (!f.estrellas) return setEstado({ ...estado, error: "Elige de 1 a 5 estrellas." });
    setEstado({ enviando: true, error: "", listo: false });
    fetch("/api/resenas", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify(f) })
      .then(r => r.json().then(j => ({ ok: r.ok && j.ok, j })))
      .then(({ ok, j }) => setEstado(ok ? { enviando: false, error: "", listo: true } : { enviando: false, error: j.error || "No pudimos enviar tu reseña.", listo: false }))
      .catch(() => setEstado({ enviando: false, error: "No pudimos enviar tu reseña. Revisa tu conexión.", listo: false }));
  };
  const lista = (datos && datos.resenas) || [];
  return (
    <section id="resenas" className="ee-sec ee-sec--soft ee-band--crema ee-rs" aria-label="Reseñas de clientes">
      <SectionHeading overline="Reseñas" title="Lo que dicen" script="nuestras clientas" />
      {lista.length > 0 && (
        <p className="ee-rs__resumen"><span className="ee-rs__prom">{String(datos.promedio).replace(".", ",")}</span>
          <span className="ee-rs__fijas" aria-hidden="true">{"★".repeat(Math.round(datos.promedio))}{"☆".repeat(5 - Math.round(datos.promedio))}</span>
          <span>{lista.length} {lista.length === 1 ? "reseña" : "reseñas"}</span></p>
      )}
      {lista.length > 0 ? (
        <div className="ee-rs__grid">
          {lista.slice(0, 9).map(r => <Testimonial key={r.id} quote={r.texto} author={r.nombre} meta={r.producto || null} stars={r.estrellas} />)}
        </div>
      ) : datos && <p className="ee-rs__vacio">Todavía no hay reseñas publicadas. ¿Ya compraste? Sé la primera en contar tu experiencia.</p>}
      {!abierto && !estado.listo && <Button variant="secondary" icon="star" onClick={() => setAbierto(true)}>Dejar mi reseña</Button>}
      {estado.listo && <p className="ee-rs__ok" role="status">¡Gracias por tu reseña! La publicaremos apenas la revisemos.</p>}
      {abierto && !estado.listo && (
        <form className="ee-rs__form" onSubmit={enviar} noValidate>
          <div className="ee-rs__fila"><span className="ee-field__label">Tu calificación</span><Estrellas valor={f.estrellas} onElegir={n => { setF({ ...f, estrellas: n }); setEstado({ ...estado, error: "" }); }} /></div>
          <Input label="Tu nombre" id="rs-nombre" value={f.nombre} onChange={campo("nombre")} maxLength={40} autoComplete="given-name" required />
          <Input label="¿Qué compraste? (opcional)" id="rs-producto" value={f.producto} onChange={campo("producto")} maxLength={80} />
          <Textarea label="Tu comentario" id="rs-texto" value={f.texto} onChange={campo("texto")} maxLength={600} rows={4} required />
          <input className="ee-rs__trampa" tabIndex={-1} autoComplete="off" aria-hidden="true" value={f.sitio} onChange={campo("sitio")} name="sitio" />
          {estado.error && <p className="ee-rs__error" role="alert">{estado.error}</p>}
          <div className="ee-row">
            <Button type="submit" disabled={estado.enviando}>{estado.enviando ? "Enviando…" : "Enviar reseña"}</Button>
            <Button variant="ghost" type="button" onClick={() => setAbierto(false)}>Cancelar</Button>
          </div>
          <span className="ee-rs__nota">Las reseñas se publican después de revisarlas. No pedimos correo ni teléfono.</span>
        </form>
      )}
    </section>
  );
}

.ee-rs__grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,260px),1fr));gap:var(--sp-5);width:100%}
.ee-rs__resumen{display:flex;flex-wrap:wrap;align-items:baseline;gap:var(--sp-3);margin:0;font:var(--type-ui);color:var(--text-muted)}
.ee-rs__prom{font:400 2.4rem/1 var(--font-display);color:var(--text-strong)}
.ee-rs__fijas{color:var(--rosa-500);letter-spacing:2px;font-size:1.1rem}
.ee-rs__vacio{font:var(--type-body);color:var(--text-body);margin:0;max-width:52ch}
.ee-rs__form{display:grid;gap:var(--sp-4);width:100%;max-width:520px;padding:var(--sp-5);background:var(--surface-card);border:1px solid var(--oro-400);border-radius:var(--radius-md);box-shadow:var(--shadow-lift)}
.ee-rs__fila{display:grid;gap:var(--sp-2)}
.ee-rs__stars{display:flex;gap:4px}
.ee-rs__star{all:unset;cursor:pointer;font-size:2rem;line-height:1;color:var(--crema-300);transition:transform var(--dur-base) var(--ease-silk),color var(--dur-base) var(--ease-silk)}
.ee-rs__star.is-on{color:var(--rosa-500)}
.ee-rs__star:hover{transform:scale(1.12)}
.ee-rs__star:focus-visible{outline:2px solid var(--rosa-700);outline-offset:2px;border-radius:4px}
.ee-rs__trampa{position:absolute;left:-9999px;width:1px;height:1px;opacity:0}
.ee-rs__error{margin:0;font:var(--fs-small)/1.5 var(--font-ui);color:var(--rosa-700)}
.ee-rs__ok{margin:0;padding:var(--sp-4) var(--sp-5);border-radius:var(--radius-md);background:var(--rosa-100);color:var(--rosa-800);font:var(--type-body)}
.ee-rs__nota{font:var(--fs-caption)/1.45 var(--font-ui);color:var(--text-muted)}
